
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_rmsrpbel_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_rmsrpbel", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.541608235884852e+00, -4.452704190211554e+00, -4.328190212887829e+00, -4.155839687259583e+00, -3.921275574532343e+00, -3.609714050694980e+00, -3.210097085590685e+00, -2.722585096700337e+00, -2.167892051809586e+00, -1.574998094193835e+00, -1.020477684585012e+00, -6.771619662286882e-01, -6.031819197668162e-01, -5.096946644027193e-01, -3.659313788415657e-01, -2.324972695559446e-01, -1.362807750406654e-01, -5.042684725676263e-02, -1.082147707426292e-02, -1.216216050001396e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


